// Generated by scripts/build-palette-data.mjs — do not edit by hand.
//
// XMind ships two tabs of 配色方案.  Every group is six colours with fixed
// roles: 0 = canvas/backdrop, 1 = secondary surface, 2..5 = branch colours,
// the last one doubles as the central-topic fill.  `strips` is the special
// three-stop artwork XMind draws for 彩虹 (one gradient per branch row).

export interface PaletteDef {
  id: string;
  name: string;
  /** Six hexes, roles as described above. */
  colors: string[];
  /** Optional 6×3 gradient stops for the 彩虹 card. */
  strips?: string[][];
  /** 彩虹 only: the 12-hue branch cycle it actually paints with. */
  cycle?: string[];
}

export interface PaletteTab { id: 'vivid' | 'classic'; label: string; groups: PaletteDef[] }

