const ALL: PaletteDef[] = PALETTE_TABS.flatMap((tab) => tab.groups);

/** Look up by the id we persist in `Document.palette`. */
export function paletteById(id: string | null | undefined): PaletteDef | null {
  if (!id) return null;
  return ALL.find((entry) => entry.id === id) ?? null;
}

/** The palette a document currently paints with, based on its branch cycle. */
export function paletteByColors(colors: string[] | null | undefined): PaletteDef | null {
  if (!colors || colors.length < 3) return null;
  const key = colors.map((c) => c.toUpperCase()).join(',');
  return ALL.find((entry) => paletteBranches(entry).map((c) => c.toUpperCase()).join(',') === key) ?? null;
}

/** The branch paints a palette actually uses on the canvas. */
export function paletteBranches(entry: PaletteDef): string[] {
  // Six swatches, fixed roles: 0/1 are the backdrop and secondary surface,
  // the last one paints the central topic, so 2..len-1 cycle over branches.
  return entry.cycle ?? entry.colors.slice(2, -1);
}

export function paletteCenter(entry: PaletteDef): string {
  return entry.colors[entry.colors.length - 1];
}
